  throw new Error('não implementado');
}

testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { responderRotaGet } from './solution.mjs';

test('objeto vira JSON', () => {
  assert.deepEqual(responderRotaGet({ nome: 'Ana' }), {
    statusCode: 200,
    contentType: 'application/json',
    body: '{"nome":"Ana"}',
  });
});

test('string vira texto', () => {
  assert.deepEqual(responderRotaGet('Olá!'), {
    statusCode: 200,
    contentType: 'text/plain; charset=utf-8',
    body: 'Olá!',
  });
});

test('limite: objeto vazio vira {}', () => {
  const resposta = responderRotaGet({});
  assert.equal(resposta.statusCode, 200);
  assert.equal(resposta.contentType, 'application/json');
  assert.equal(resposta.body, '{}');
});

test('valor vazio: lança erro', () => {
  assert.throws(() => responderRotaGet(undefined), /vazio/);
  assert.throws(() => responderRotaGet(null), /vazio/);
});

solutionCode:
export function responderRotaGet(valor) {
  if (valor === undefined || valor === null) {
    throw new Error('valor vazio não pode ser enviado');
  }

  if (typeof valor === 'string') {
    return {
      statusCode: 200,
      contentType: 'text/plain; charset=utf-8',
      body: valor,
    };
  }

  return {
    statusCode: 200,
    contentType: 'application/json',
    body: JSON.stringify(valor),
  };
}
